import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.CZ6YNuB6.js";const d="/Qonnectra-docs/pr-29/images/manual/teil-b/permission_users.jpg",s="/Qonnectra-docs/pr-29/images/manual/teil-b/permission_user_form.jpg",o="/Qonnectra-docs/pr-29/images/manual/teil-b/permission_model_list.jpg",a="/Qonnectra-docs/pr-29/images/manual/teil-b/permission_route_list.jpg",l="/Qonnectra-docs/pr-29/images/manual/teil-b/permission_group_form.jpg",u="/Qonnectra-docs/pr-29/images/manual/teil-b/permission_model_add.jpg",k=JSON.parse('{"title":"19. Rollen und Rechte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/19-rollen-und-rechte.md","filePath":"manual/teil-b-betrieb-admin-qgis/19-rollen-und-rechte.md"}'),c={name:"manual/teil-b-betrieb-admin-qgis/19-rollen-und-rechte.md"};function h(p,e,g,b,m,f){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_19-rollen-und-rechte" tabindex="-1">19. Rollen und Rechte <a class="header-anchor" href="#_19-rollen-und-rechte" aria-label="Permalink to &quot;19. Rollen und Rechte&quot;">​</a></h1><p>Was ein Konto in Qonnectra sehen und ändern darf, legen Sie im Administrationsbereich fest. Dieses Kapitel beschreibt, aus welchen Teilen sich die Rechte eines Kontos zusammensetzen, wie Sie Konten und Gruppen anlegen und welche Rollen Qonnectra mitbringt. Wie Sie den Administrationsbereich erreichen und bedienen, beschreibt Kapitel <a href="./20-administrationsbereich.html">Der Administrationsbereich</a>.</p><p><img src="'+d+'" alt="Screenshot der Benutzerliste im Administrationsbereich mit drei Konten in den Gruppen „Admin“, „Editor“ und „Viewer“" data-zoomable="true"></p><p>Die Rechte eines Kontos ergeben sich aus drei voneinander unabhängigen Einstellungen:</p><ul><li><strong>Gruppenmitgliedschaft</strong> – die Gruppe bestimmt, was das Konto in der Weboberfläche darf: welche Objektarten es ansehen, bearbeiten und löschen kann (<strong>Modellrechte</strong>, Abschnitt <a href="#_19-2-modellrechte-zugriff-je-datenmodell">Modellrechte</a>) und welche Menüpunkte es öffnen darf (<strong>Routenrechte</strong>, Abschnitt <a href="#_19-3-routenrechte-zugriff-je-menupunkt">Routenrechte</a>).</li><li><strong>„Mitarbeiter-Status“</strong> – erlaubt die Anmeldung im Administrationsbereich und, zusammen mit dem passenden Routenrecht, das Lesen der Systemprotokolle („Logs“) in der Weboberfläche.</li><li><strong>„Administrator-Status“</strong> – macht das Konto zum <strong>Superuser</strong>, der jede Prüfung umgeht, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Benutzerliste zeigt als Spalte nur den „Mitarbeiter-Status“, nicht den „Administrator-Status“. Welche Konten Superuser sind, sehen Sie über den Filter „Nach Administrator-Status“ rechts neben der Liste oder im Formular des Kontos.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Gruppe „Admin“ und der Administrationsbereich haben nichts miteinander zu tun, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</p></div><h2 id="_19-1-benutzende-und-gruppen-anlegen" tabindex="-1">19.1 Benutzende und Gruppen anlegen <a class="header-anchor" href="#_19-1-benutzende-und-gruppen-anlegen" aria-label="Permalink to &quot;19.1 Benutzende und Gruppen anlegen&quot;">​</a></h2><p>Konten pflegen Sie unter „Authentifizierung und Autorisierung“ → „Benutzer“. Eine Selbstregistrierung gibt es nicht, und die Weboberfläche kann weder Konten anlegen noch Passwörter zurücksetzen.</p><ol><li>Klicken Sie in der Benutzerliste oben rechts auf „Benutzer hinzufügen“.</li><li>Geben Sie unter „Benutzername“ einen Namen und zweimal das Passwort ein und klicken Sie auf „Sichern und weiter bearbeiten“.</li><li>Tragen Sie im folgenden Formular unter „Persönliche Informationen“ Vor- und Nachnamen und die E-Mail-Adresse ein.</li><li>Wählen Sie unter „Berechtigungen“ im Feld „Gruppen“ die Gruppe aus, siehe Abschnitt <a href="#_19-5-typische-rollenprofile-betrachten-bearbeiten-verwalten">Typische Rollenprofile</a>.</li><li>Klicken Sie auf „Sichern“.</li></ol><p><img src="'+s+'" alt="Screenshot des Benutzerformulars im Administrationsbereich mit Hervorhebung der drei Status-Felder und der Gruppen unten im Abschnitt „Berechtigungen“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein Konto ohne Gruppe kann sich anmelden, darf aber keine Seite der Weboberfläche öffnen. Es sieht nach der Anmeldung nur die Seite „Kein Zugriff“ mit dem Hinweis „Deinem Konto ist noch keine Rolle zugewiesen, die eine Seite freigibt. Wende dich an deine Administration.“ Wählen Sie die Gruppe deshalb gleich beim Anlegen.</p></div><p>Gehört ein Konto mehreren Gruppen an, gilt je Objektart die höchste Stufe, die eine seiner Gruppen vergibt. Ein Konto in „Viewer“ und „Editor“ darf also bearbeiten.</p><p>Ein Konto, das nicht mehr arbeiten soll, deaktivieren Sie, statt es zu löschen: Entfernen Sie den Haken bei „Aktiv“. Die Anmeldung schlägt dann fehl, Einträge im Protokoll und im Änderungsverlauf behalten aber ihren Bezug zu dem Konto.</p><p>Das Passwort eines Kontos setzen Sie im Benutzerformular über den Link unter dem Feld „Passwort“ neu. Das alte Passwort lässt sich nicht einsehen; Qonnectra speichert nur einen daraus berechneten Wert.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein geändertes Passwort beendet laufende Sitzungen der Weboberfläche nicht sofort. Die Anmeldung dort hält bis zu sieben Tage und verlängert sich, solange das Konto aktiv bleibt. Wollen Sie ein Konto sofort sperren, deaktivieren Sie es.</p></div><p>Gruppen pflegen Sie unter „Authentifizierung und Autorisierung“ → „Gruppen“. Das Formular einer Gruppe zeigt unter dem Feld „Berechtigungen“ ihre „Modell-Zugriffsrechte“ und „Seiten-Zugriffsrechte“, die Sie dort auch direkt bearbeiten; was sie bedeuten, beschreiben die folgenden Abschnitte. Eine neue Gruppe hat zunächst kein Modellrecht. Wie Sie sie mit den Rechten einer bestehenden Gruppe beginnen, beschreibt Abschnitt <a href="#_19-6-eigene-rollen-anlegen-und-rechte-erganzen">Eigene Rollen anlegen und Rechte ergänzen</a>.</p><h2 id="_19-2-modellrechte-zugriff-je-datenmodell" tabindex="-1">19.2 Modellrechte: Zugriff je Datenmodell <a class="header-anchor" href="#_19-2-modellrechte-zugriff-je-datenmodell" aria-label="Permalink to &quot;19.2 Modellrechte: Zugriff je Datenmodell&quot;">​</a></h2><p>Die <strong>Modellrechte</strong> legen je Gruppe und Objektart fest, was ein Konto mit den Daten tun darf. Sie stehen unter „Api“ → „Modell-Zugriffsrechte“, eine Zeile je Gruppe und Objektart.</p><p><img src="'+o+'" alt="Screenshot der Modell-Zugriffsrechte, gefiltert auf die Gruppe „Editor“, mit Hervorhebung der Filterleiste rechts und der Spalte „Zugriffsebene“" data-zoomable="true"></p><p>Jede Zeile hat eine von vier Zugriffsebenen:</p><ul><li>„Kein Zugriff“ – die Objektart bleibt verborgen; jede Anfrage scheitert.</li><li>„Nur Ansehen“ – lesen.</li><li>„Ansehen und Bearbeiten“ – lesen, anlegen und ändern, aber nicht löschen.</li><li>„Vollzugriff“ – zusätzlich löschen.</li></ul><p>Die Spalte „Zugriffsebene“ lässt sich direkt in der Liste ändern, siehe Abschnitt <a href="./20-administrationsbereich.html#_20-2-suchen-filtern-und-massenbearbeitung">Suchen, Filtern und Massenbearbeitung</a>.</p><p>Die Objektarten stehen in der Spalte „Modellname“ mit ihrem technischen Namen. Wirksam sind diese Zeilen:</p><table tabindex="0"><thead><tr><th>Modellname</th><th>Bereich der Weboberfläche</th></tr></thead><tbody><tr><td><code>trench</code>, <code>conduit</code>, <code>microduct</code></td><td>Trassen, Rohre und Mikrorohre; <code>conduit</code> auch für den Excel-Import der Rohrverwaltung</td></tr><tr><td><code>trenchconduitconnection</code>, <code>trenchconduitcanvas</code></td><td>Rohrzuordnung und Grabenprofil</td></tr><tr><td><code>microductconnection</code>, <code>nodetrenchselection</code></td><td>Verbindungen der Mikrorohre und Grabenauswahl in der Rohrverzweigung</td></tr><tr><td><code>node</code>, <code>address</code>, <code>residentialunit</code>, <code>area</code></td><td>Netzknoten, Adressen, Wohneinheiten, Gebiete</td></tr><tr><td><code>cable</code>, <code>fiber</code>, <code>fibersplice</code>, <code>cablelabel</code></td><td>Kabel, Fasern, Spleiße und Kabelbeschriftungen im Netzschema</td></tr><tr><td><code>microductcableconnection</code></td><td>Verknüpfung von Kabeln mit Mikrorohren im Netzschema</td></tr><tr><td><code>nodeslotconfiguration</code>, <code>nodestructure</code>, <code>container</code>, <code>nodeslotclipnumber</code>, <code>nodeslotdivider</code></td><td>Aufbau eines Netzknotens, samt Clip-Nummern und Trennlinien der Slot-Ansicht</td></tr><tr><td><code>pipelinerecord</code>, <code>pipelineinquiryarea</code></td><td>Auskünfte und Auskunftsbereiche der Leitungsauskunft</td></tr><tr><td><code>featurefiles</code></td><td>Anhänge</td></tr><tr><td><code>wmssource</code>, <code>wmslayer</code></td><td>externe Kartendienste und ihre Layer in der Legende der Karte, siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-4-externe-wms-quellen-als-hintergrund-einbinden">Externe WMS-Quellen als Hintergrund einbinden</a></td></tr></tbody></table><p>Neben den Objektarten bietet das Feld „Modellname“ die Zeile „* (jedes Modell ohne eigene Zeile)“. Ihre Stufe gilt in der Gruppe für jede Objektart, für die die Gruppe keine eigene Zeile hat. Daraus ergibt sich die Stufe eines Kontos je Objektart:</p><ul><li>Innerhalb einer Gruppe geht die Zeile der Objektart der Zeile <code>*</code> vor, auch wenn sie weniger erlaubt.</li><li>Hat die Gruppe weder die eine noch die andere, gilt für sie „Kein Zugriff“.</li><li>Zwischen mehreren Gruppen eines Kontos gilt die höchste Stufe, die eine von ihnen ergibt.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine Zeile, die weniger erlaubt, schränkt nur ihre eigene Gruppe ein. Steht ein Konto zusätzlich in einer Gruppe, deren Zeile <code>*</code> mehr erlaubt, gilt für die Objektart das Mehr.</p></div><p>Sieben weitere Zeilen bringt Qonnectra mit, sie wirken aber nicht: <code>projects</code>, <code>flags</code>, <code>containertype</code>, <code>typeofwork</code>, <code>requestreason</code>, <code>qgisproject</code> und <code>logentry</code>. Dasselbe gilt für alle übrigen Einträge, die das Feld „Modellname“ zur Auswahl anbietet, etwa die Stammdaten. Projekte, Kennzeichen, Container-Typen und die Auswahllisten der Leitungsauskunft sind wie alle übrigen Stammdaten – Status, Rohrtypen, Firmen – für jedes angemeldete Konto lesbar und lassen sich nur im Administrationsbereich ändern. Wer die Systemprotokolle lesen darf, regeln „Mitarbeiter-Status“ und Routenrecht, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine geänderte Zugriffsebene greift nicht sofort. Qonnectra hält die Rechte eines Kontos bis zu fünf Minuten zwischengespeichert. Die Navigationsleiste zeigt die neuen Rechte erst, wenn das Konto die Seite neu lädt, und auch dann mit bis zu 30 Sekunden Verzögerung. Eine Aktion kann in dieser Zeit noch mit dem alten Recht gelingen oder scheitern.</p></div><h2 id="_19-3-routenrechte-zugriff-je-menupunkt" tabindex="-1">19.3 Routenrechte: Zugriff je Menüpunkt <a class="header-anchor" href="#_19-3-routenrechte-zugriff-je-menupunkt" aria-label="Permalink to &quot;19.3 Routenrechte: Zugriff je Menüpunkt&quot;">​</a></h2><p>Die <strong>Routenrechte</strong> sperren Seiten der Weboberfläche für eine Gruppe. Sie stehen unter „Api“ → „Seiten-Zugriffsrechte“. Jede Zeile nennt eine Gruppe, ein „Route-Muster“ und ob es „Erlaubt“ ist.</p><p><img src="'+a+'" alt="Screenshot der Seiten-Zugriffsrechte mit den drei mitgelieferten Zeilen für das Muster „/admin/*“ in der Mitte" data-zoomable="true"></p><p>Mitgeliefert ist für jede der drei Gruppen genau eine Zeile: Das Muster <code>/admin/*</code> ist für „Admin“ erlaubt und für „Editor“ und „Viewer“ gesperrt. Es betrifft in der Weboberfläche nur einen Menüpunkt, die „Logs“ am Fuß der Navigationsleiste. Alles, wofür keine Zeile existiert, ist erlaubt.</p><p>Eine Seite wird über ihren <strong>Seitenschlüssel</strong> angesprochen: den Pfad der Seite ohne die Nummer des Projekts und ohne die Kennungen einzelner Objekte. Die Karte hat in jedem Projekt den Schlüssel <code>/map</code>. Das Route-Muster ist ein Seitenschlüssel oder ein Muster mit <code>/*</code> am Ende:</p><ul><li><code>/valuation</code> – die Seite und alle Seiten darunter.</li><li><code>/network-schema/*</code> – nur die Seiten darunter, etwa das Subnetz, nicht das Netzschema selbst.</li><li><code>/*</code> – alle Seiten.</li></ul><p>Großbuchstaben, Leerzeichen und ein fehlender Schrägstrich am Anfang weist das Formular beim Speichern ab. Einen Pfad aus der Adresszeile des Browsers wie <code>/project/2/valuation</code> nimmt es dagegen an, obwohl er keine Seite trifft; tragen Sie nur den Schlüssel ein. Die Schlüssel der Menüpunkte:</p><table tabindex="0"><thead><tr><th>Menüpunkt</th><th>Schlüssel</th><th>Menüpunkt</th><th>Schlüssel</th></tr></thead><tbody><tr><td>„Dashboard“</td><td><code>/dashboard</code></td><td>„Verwaltung“ (Rohr)</td><td><code>/conduit</code></td></tr><tr><td>„Karte“</td><td><code>/map</code></td><td>„Zuordnung“ (Rohr)</td><td><code>/trench</code></td></tr><tr><td>„Störungsanalyse“</td><td><code>/fault-simulation</code></td><td>„Verzweigung“ (Rohr)</td><td><code>/pipe-branch</code></td></tr><tr><td>„Nachverdichtung“</td><td><code>/post-compaction</code></td><td>„Mikrorohre“</td><td><code>/house-connections</code></td></tr><tr><td>„Leitungsauskunft“</td><td><code>/pipeline-records</code></td><td>„Netzschema“</td><td><code>/network-schema</code></td></tr><tr><td>„Wertermittlung“</td><td><code>/valuation</code></td><td>„Faserweg“</td><td><code>/trace</code></td></tr><tr><td>„Adressen“</td><td><code>/address</code></td><td>„Einstellungen“</td><td><code>/settings</code></td></tr><tr><td>„Logs“</td><td><code>/admin/logs</code></td><td></td><td></td></tr></tbody></table><p>Einige Seiten, die die Ansichten öffnen, haben einen eigenen Schlüssel unter dem des Menüpunkts: <code>/network-schema/node</code> (Subnetz eines Netzknotens), <code>/pipe-branch/node</code> (Rohrverzweigung eines Netzknotens), <code>/address/unit</code> (Wohneinheit), <code>/pipeline-records/new</code> und <code>/pipeline-records/inquiry</code> (neue Auskunft und Auskunftsabfrage). Eine Zeile <code>/network-schema</code> sperrt das Subnetz deshalb mit.</p><p>Umfassen mehrere Zeilen eine Seite, entscheidet die genaueste: Ist <code>/address</code> gesperrt und <code>/address/unit</code> erlaubt, öffnen sich die Wohneinheiten, die Liste der Adressen nicht. Widersprechen sich gleich genaue Zeilen, auch aus verschiedenen Gruppen eines Kontos, gewinnt „Erlaubt“.</p><p>Eine gesperrte Seite verschwindet aus der Navigationsleiste. Wird sie trotzdem aufgerufen, etwa über ein Lesezeichen, leitet die Weboberfläche ohne Meldung zur Karte um. Ist auch die Karte gesperrt, leitet sie zur obersten Seite der Navigationsleiste um, die das Konto öffnen darf, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.html#_18-3-fehlende-rechte-erkennen">Fehlende Rechte erkennen</a>. Ist keine Seite erlaubt, erscheint die Seite „Kein Zugriff“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine Gruppe, die mit <code>/*</code> alles erlaubt, hebt die Sperre einer genaueren Zeile in einer anderen Gruppe desselben Kontos nicht auf. Ist <code>/valuation</code> für „Viewer“ gesperrt, bleibt die Wertermittlung für ein Konto in „Viewer“ und einer Gruppe mit <code>/*</code> gesperrt.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Bis Version 1.7 stand die Nummer des Projekts am Ende des Pfads, und eine Seite zu sperren brauchte zwei Zeilen, etwa <code>/valuation</code> und <code>/valuation/*</code>. Seither umfasst ein Muster mit <code>/*</code> nur noch die Seiten darunter: <code>/valuation/*</code> allein sperrt nichts mehr, <code>/network-schema/*</code> allein nur noch das Subnetz. Prüfen Sie die Seiten-Zugriffsrechte nach der Aktualisierung einer älteren Installation und ergänzen Sie, wo nötig, die Zeile ohne <code>/*</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Routenrechte sind kein Schutz der Daten. Sie verbergen einen Menüpunkt, nicht die Daten dahinter: Dieselben Daten erscheinen in anderen Ansichten und sind über die Schnittstelle abrufbar. Was eine Gruppe nicht sehen darf, sperren Sie über die Modellrechte.</p></div><h2 id="_19-4-superuser-gegenuber-gruppenmitgliedschaft" tabindex="-1">19.4 Superuser gegenüber Gruppenmitgliedschaft <a class="header-anchor" href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft" aria-label="Permalink to &quot;19.4 Superuser gegenüber Gruppenmitgliedschaft&quot;">​</a></h2><p>Ein Konto mit „Administrator-Status“ ist <strong>Superuser</strong>. Für ein solches Konto gelten weder Modell- noch Routenrechte: Es sieht jeden Menüpunkt, darf jede Objektart löschen und sieht auch die Daten, für die seine Gruppen kein Recht vergeben. Seine Gruppenmitgliedschaft spielt keine Rolle.</p><p>Für den Administrationsbereich gilt anderes als für die Weboberfläche:</p><ul><li>Anmelden kann sich dort nur ein Konto mit „Mitarbeiter-Status“.</li><li>Bearbeiten kann es dort nur, was ihm das Feld „Berechtigungen“ im Gruppen- oder Benutzerformular erlaubt. Bei den mitgelieferten Gruppen ist dieses Feld leer.</li></ul><p><img src="'+l+'" alt="Screenshot des Formulars der Gruppe „Admin“ mit Hervorhebung des leeren Feldes „Berechtigungen“ unter dem Namen" data-zoomable="true"></p><p>In der Praxis ist der Administrationsbereich deshalb dem Superuser-Konto vorbehalten. Ein Konto, das nur „Mitarbeiter-Status“ hat, kommt zwar hinein, sieht dort aber statt der Bereiche nur die Meldung „Das Benutzerkonto besitzt nicht die nötigen Rechte, um etwas anzusehen oder zu ändern.“ Bei einem Konto ohne den Status scheitert schon die Anmeldung: „Bitte Benutzername und Passwort für einen Staff-Account eingeben.“</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Berechtigungen im Gruppen- und im Benutzerformular („Can add …“, „Can change …“) wirken nur im Administrationsbereich. Auf die Weboberfläche haben sie keinen Einfluss – dort zählen ausschließlich die Modell- und Routenrechte.</p></div><p>Die „Logs“ der Weboberfläche öffnen sich nur, wenn beides zutrifft: Das Konto hat „Mitarbeiter-Status“, und seine Gruppe darf die Seite <code>/admin/logs</code> öffnen, etwa über das Muster <code>/admin/*</code> – von den mitgelieferten Gruppen nur „Admin“. Die „Log-Einträge“ im Administrationsbereich sieht ohnehin nur das Superuser-Konto.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Fehlt eine der beiden Voraussetzungen, landet das Konto ohne Meldung in der Karte. Ein Mitglied der Gruppe „Admin“ ohne „Mitarbeiter-Status“ sieht den Menüpunkt „Logs“ sogar, kommt aber nicht auf die Seite.</p></div><p>Der erste Superuser entsteht bei der Einrichtung der Instanz aus der Konfiguration, siehe Abschnitt <a href="./28-betrieb-der-instanz.html#_28-2-konfiguration-uber-umgebungsvariablen">Konfiguration über Umgebungsvariablen</a>. Legen Sie für die tägliche Arbeit eigene Konten an und nutzen Sie den Superuser nur für die Verwaltung.</p><h2 id="_19-5-typische-rollenprofile-betrachten-bearbeiten-verwalten" tabindex="-1">19.5 Typische Rollenprofile: Betrachten, Bearbeiten, Verwalten <a class="header-anchor" href="#_19-5-typische-rollenprofile-betrachten-bearbeiten-verwalten" aria-label="Permalink to &quot;19.5 Typische Rollenprofile: Betrachten, Bearbeiten, Verwalten&quot;">​</a></h2><p>Qonnectra bringt drei Gruppen mit, die drei Rollen entsprechen:</p><table tabindex="0"><thead><tr><th>Gruppe</th><th>Fachdaten</th><th>Menüpunkt „Logs“</th><th>Typisch für</th></tr></thead><tbody><tr><td>„Viewer“</td><td>„Nur Ansehen“</td><td>ausgeblendet</td><td>Auskunft, Entscheidung, externe Stellen</td></tr><tr><td>„Editor“</td><td>„Ansehen und Bearbeiten“</td><td>ausgeblendet</td><td>Sachbearbeitung, Dokumentation</td></tr><tr><td>„Admin“</td><td>„Vollzugriff“</td><td>sichtbar, öffnet sich mit „Mitarbeiter-Status“</td><td>fachlich Verantwortliche, die auch löschen</td></tr></tbody></table><p>Der wichtigste Unterschied zwischen „Editor“ und „Admin“ ist das Löschen. Mit „Editor“ lässt sich in der Weboberfläche nichts entfernen – kein Rohr, kein Anhang, keine Slot-Konfiguration, auch keine Faser von einem Port und keine Verknüpfung zwischen Kabel und Mikrorohr. „Ansehen und Bearbeiten“ umfasst dagegen das Anlegen: Rohre, Anhänge, Wohneinheiten und Auskünfte legt ein „Editor“ selbst an, auch über den Excel-Import der Rohrverwaltung.</p><p>Die Weboberfläche zeigt jeder Rolle dieselben Schaltflächen. Ob eine Aktion erlaubt ist, entscheidet sich erst beim Speichern; scheitert sie, erscheint in der Regel die Meldung „Deine Rolle erlaubt diese Aktion nicht. Wende dich an deine Administration.“, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.html#_18-3-fehlende-rechte-erkennen">Fehlende Rechte erkennen</a>. Weisen Sie Nutzende mit der Rolle „Viewer“ darauf hin.</p><p>Eine eigene Rolle legen Sie als Abwandlung einer dieser drei an, siehe Abschnitt <a href="#_19-6-eigene-rollen-anlegen-und-rechte-erganzen">Eigene Rollen anlegen und Rechte ergänzen</a>.</p><h2 id="_19-6-eigene-rollen-anlegen-und-rechte-erganzen" tabindex="-1">19.6 Eigene Rollen anlegen und Rechte ergänzen <a class="header-anchor" href="#_19-6-eigene-rollen-anlegen-und-rechte-erganzen" aria-label="Permalink to &quot;19.6 Eigene Rollen anlegen und Rechte ergänzen&quot;">​</a></h2><p>Eine eigene Rolle ist eine Gruppe mit eigenen Modell- und Routenrechten. Am schnellsten beginnen Sie sie mit den Rechten der Gruppe, die ihr am nächsten kommt:</p><ol><li>Öffnen Sie „Authentifizierung und Autorisierung“ → „Gruppen“ und klicken Sie oben rechts auf „Gruppe hinzufügen“.</li><li>Geben Sie den „Name“ ein und wählen Sie unter „Berechtigungen übernehmen von“ die Vorlage.</li><li>Tragen Sie unter „Modell-Zugriffsrechte“ und „Seiten-Zugriffsrechte“ nur die Zeilen ein, die von der Vorlage abweichen sollen.</li><li>Klicken Sie auf „Sichern“.</li></ol><p>Beim Sichern übernimmt die neue Gruppe alle Zeilen der Vorlage, die sie nicht schon hat; eine Zeile, die Sie im Formular für dieselbe Objektart oder dasselbe Muster eingetragen haben, hat Vorrang. Danach sind beide Gruppen unabhängig: Spätere Änderungen an der Vorlage übernimmt die neue Gruppe nicht. „Berechtigungen übernehmen von“ gibt es nur beim Anlegen.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Berechtigungen übernehmen von“ und das Feld „Berechtigungen“ darüber haben nichts miteinander zu tun. Das Feld „Berechtigungen“ wirkt nur im Administrationsbereich, siehe Abschnitt <a href="#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>; lassen Sie es leer.</p></div><p>Eine einzelne Zeile ergänzen Sie im Formular der Gruppe oder über die Liste:</p><ol><li>Öffnen Sie „Api“ → „Modell-Zugriffsrechte“ und klicken Sie oben rechts auf „Modell-Zugriffsrecht hinzufügen“.</li><li>Wählen Sie die „Gruppe“ und unter „Modellname“ die Objektart, siehe Abschnitt <a href="#_19-2-modellrechte-zugriff-je-datenmodell">Modellrechte</a>.</li><li>Wählen Sie die „Zugriffsebene“ und klicken Sie auf „Sichern“.</li></ol><p><img src="'+u+'" alt="Screenshot des Formulars „Modell-Zugriffsrecht hinzufügen“ mit einer eigenen Gruppe „Auskunft“, dem Modellnamen „wmssource“ und der Zugriffsebene „Nur Ansehen“ oben im Formular" data-zoomable="true"></p><p>Für eine Rolle, die fast überall dieselbe Stufe hat, genügt eine Zeile „* (jedes Modell ohne eigene Zeile)“ und je eine Zeile für die Ausnahmen.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die mitgelieferten Gruppen enthalten seit Version 1.8 auch die Rechte für externe Kartendienste (<code>wmssource</code>), die Grabenauswahl der Rohrverzweigung (<code>nodetrenchselection</code>) sowie Clip-Nummern und Trennlinien der Slot-Ansicht (<code>nodeslotclipnumber</code>, <code>nodeslotdivider</code>): „Admin“ mit „Vollzugriff“, „Editor“ mit „Ansehen und Bearbeiten“, „Viewer“ mit „Nur Ansehen“. Die Aktualisierung einer älteren Installation ergänzt diese Zeilen nur in Gruppen, die genau „Admin“, „Editor“ oder „Viewer“ heißen, und lässt Zeilen, die dort schon bestehen, unverändert. Eigenen Gruppen fehlen sie, und ihre Konten sehen z. B. die externen Kartendienste nicht. Ergänzen Sie dort die vier Zeilen oder eine Zeile <code>*</code>.</p></div>',70)])])}const z=n(c,[["render",h]]);export{k as __pageData,z as default};
